import { escapeTablePipe } from './task-record';

// ─── Sub-task roster (0123) ───────────────────────────────────────────────

/** Auto-gen markers for the parent `## Plan` sub-task roster block. */
export const ROSTER_START = '<!-- AUTO-GENERATED by spur task refresh-roster -->';

/** Closing marker of the auto-generated sub-task roster block. */
export const ROSTER_END = '<!-- END AUTO-GENERATED -->';

/** Matches a full prior roster region (markers inclusive) for idempotent rewrite. */
export const ROSTER_REGION_RE = /<!--[ \t]*AUTO-GENERATED[^>]*-->[\s\S]*?<!--[ \t]*END[ \t]*AUTO-GENERATED[^>]*-->/g;

/** Render the sub-task roster table — one row per child (WBS · title · status). */
export function renderRosterTable(rows: { wbs: string; name: string; status: string }[]): string {
    const header = '| WBS | Sub-task | Status |\n| --- | -------- | ------ |';
    const body = rows.map((r) => `| ${r.wbs} | ${escapeTablePipe(r.name)} | ${r.status} |`).join('\n');
    return `${header}\n${body}`;
}
